export async function handleMobileDashboard(req: Request, res: Response) {
  const userId = req.headers['x-user-id'] as string;

  // Concurrently fetch from internal microservices over low-latency private VPC
  const [profile, recentOrders, notifications] = await Promise.all([
    userService.getCompactProfile(userId),
    orderService.getRecentSummary(userId, 3),
    notificationService.getUnreadCount(userId),
  ]);

  // Return single, optimized payload tailored specifically for mobile screens
  res.json({
    user: profile,
    orders: recentOrders,
    unreadAlerts: notifications,
  });
}
